return $input.all().map(({ json }) => ({
  json: {
    listingId: json.listingId || json.id,
    title: json.title || json.name,
    location: json.location || json.city,
    isSuperhost: Boolean(json.isSuperhost),
    rating: json.rating ?? null,
    reviewsCount: json.reviewsCount ?? 0,
    occupancy30dPct: json.occupancy30dPct ?? json.trailingOccupancy30D ?? null,
    occupancy90dPct: json.occupancy90dPct ?? json.trailingOccupancy90D ?? null,
    nightlyPriceUsd: json.nightlyPrice ?? json.priceUsd ?? null,
    highDemandFlag: Number(json.occupancy30dPct ?? json.trailingOccupancy30D ?? 0) >= 70,
    url: json.url || '',
    scrapedAt: json.scrapedAt
  }
}));
